box.script:
// Beautiful color palette
var colors = [
  ["bg-blue-500", "text-white"],
  ["bg-emerald-500", "text-white"],
  ["bg-purple-500", "text-white"],
  ["bg-pink-500", "text-white"],
  ["bg-amber-500", "text-black"],
  ["bg-cyan-500", "text-black"],
  ["bg-rose-500", "text-white"],
  ["bg-indigo-500", "text-white"],
  ["bg-teal-500", "text-white"],
  ["bg-orange-500", "text-white"],
  ["bg-lime-500", "text-black"],
  ["bg-sky-500", "text-white"],
  ["bg-violet-500", "text-white"],
  ["bg-fuchsia-500", "text-white"],
  ["bg-yellow-400", "text-black"]
]

var colorIndex = 0
var keyCount = 0

// Add initial placeholder
var placeholderBox = document.createElement("text-gray-500")
var placeholder = document.createText("Waiting for input...")
placeholderBox.append(placeholder)
self.append(placeholderBox)

// Listen for keypress events
document.addEventListener("keypress", Fn.new { |event|
  // Remove placeholder on first keypress
  if (keyCount == 0) {
    if (self.childCount > 0) {
      var firstChild = self.firstChild
      if (firstChild != null) {
        self.removeChild(firstChild)
      }
    }
  }

  keyCount = keyCount + 1

  // Get colors for this key
  var colorPair = colors[colorIndex]
  var bgColor = colorPair[0]
  var textColor = colorPair[1]

  colorIndex = (colorIndex + 1) % colors.count
  var borderColor = colors[colorIndex][0].replace("bg-", "border-")

  // Create styled box for the key
  var keyBox = document.createElement("border-1 " + borderColor + " " + bgColor + " " + textColor)

  // Special handling for space and special chars
  var keyText = event["key"]
  if (keyText == " ") {
    keyText = "␣"
  } else if (keyText == "\n") {
    keyText = "↵"
  } else if (keyText == "\t") {
    keyText = "⇥"
  }

  // Create text node and append
  var textNode = document.createText(keyText)
  keyBox.append(textNode)

  // Add the key box to the container
  self.append(keyBox)
})
